"""Write ``numpy_sr/_ops.py``: the extension's ops as typed protocols."""

from __future__ import annotations

import sys

HEADER = '''\
"""Generated by python/_numpy_sr/gen_ops.py from meson's op list; do not edit."""

from __future__ import annotations

from typing import Final, Protocol, TypeVar

import numpy as np
import numpy.typing as npt

from ._numpy_sr import Accuracy

__all__ = ["OPERATIONS", "SIGNATURES", "OracleOps", "TargetOps"]

_F64 = npt.NDArray[np.float64]
# The op's result has the dtype of its input.
FloatArray = TypeVar("FloatArray", npt.NDArray[np.float32], _F64)

OPERATIONS: Final = {ops}
SIGNATURES: Final = {{{sigs}}}
'''

# The method per Signature (operations.h).
TARGET = {
    "Unary": """
    def {op}(self, x: FloatArray, accuracy: Accuracy = Accuracy.High) -> FloatArray: ...
""",
}

ORACLE = {
    "Unary": """
    def {op}(self, x: FloatArray) -> tuple[FloatArray, _F64]: ...
""",
}


def render(specs: list[str]) -> str:
    sigs = dict(spec.split(":") for spec in specs)
    ops = sorted(sigs)
    # repr() quotes with ', and ruff's formatter wants ".
    names = ", ".join(f'"{op}"' for op in ops)
    pairs = ", ".join(f'"{op}": "{sigs[op]}"' for op in ops)
    out = [
        HEADER.format(ops=f"({names},)" if len(ops) == 1 else f"({names})", sigs=pairs)
    ]
    for name, method in (("TargetOps", TARGET), ("OracleOps", ORACLE)):
        out.append(f"\n\nclass {name}(Protocol):")
        out.extend(method[sigs[op]].format(op=op) for op in ops)
    return "".join(out)


if __name__ == "__main__":
    output, *specs = sys.argv[1:]  # op:Signature
    with open(output, "w") as f:
        f.write(render(specs))
